function setStep(value){closeSurveyDialog();cancelAnimationFrame(motionRequest);state.motionProgress=1;if(state.view==='farms')state.pinned=null;state.step=Math.max(0,Math.min(model.events.length,Math.round(Number(value)||0)));updateCurrent();remember();if(state.view==='farms')animateDevices();}
