 const a=event.arguments||{},o=event.result||{},start=Number(a.start_ridge??a.start),end=Number(a.end_ridge??a.end??start);
 if(Number.isInteger(start)&&Number.isInteger(end)&&start>=0&&end>=start&&end<64)return Array.from({length:end-start+1},(_,i)=>start+i);
