 if(batch)rows.push(['Batch quantity',number(batch.quantity_kg,2)+' kg'],['Batch moisture',number(batch.moisture_pct,2)+'%'],['Batch status',batch.status||'Recorded'],['Origin',farmLabel(batch.origin_farm_id)]);
 if(actor==='Warehouse'){const w=snapshot.warehouse;rows.push(['Fertilizer stock',number(w.stock.fertilizer_kg,1)+' kg'],['Fuel stock',number(w.stock.fuel_liters,1)+' L'],['Chemical stock',number(w.stock.pesticide_liters,1)+' L'],['Grain batches',String(Object.keys(w.grain_batches).length)]);}
 if(device?._battery_pct!==undefined)rows.push(['Stored battery',number(device._battery_pct,1)+'%'],['Charging record',device._charging?'Charging':'Idle']);
 if(device?._fuel_tank_l!==undefined)rows.push(['Fuel tank',number(device._fuel_tank_l,1)+' L'],['Mounted implement',device._attached_implement||'None']);
 const targets=ridges.map(id=>snapshot.farms[farmId].ridges[id]);
 if(targets.length){const avg=key=>targets.reduce((n,r)=>n+r[key],0)/targets.length;rows.push(['Target root-zone VWC',number(avg('root_vwc'),3)+' m³/m³'],['Target disease pressure',number(avg('disease_pressure'),3)+' index'],['Target growth stage',[...new Set(targets.map(r=>r.growth_stage))].join(', ')],['Target harvested',`${targets.filter(r=>r.harvested).length} / ${targets.length} ridges`]);}
 if(!rows.length){const f=snapshot.farms[farmId].ridges,mean=key=>f.reduce((n,r)=>n+r[key],0)/f.length;rows.push(['Context plot',farmLabel(farmId)],['Plot root-zone VWC',number(mean('root_vwc'),3)+' m³/m³'],['Plot disease pressure',number(mean('disease_pressure'),3)+' index'],['Coverage','Plot context; no ridge target']);}
