 host.innerHTML=`<div class="pip-head"><div><strong>${state.pinned?'Pinned action':'Action preview'} · ${event.sequence}</strong><small>${dateLabel(event.datetime_after)}</small></div><button class="close-button" data-action="unpin" aria-label="Close action preview">${icon('close')}</button></div><div class="mini-scene" id="mini-scene"></div><div class="event-detail"><div class="mini-heading">${esc(scopeLabel(event))}</div><strong style="font-size:12px;font-weight:500">${esc(event.title)}</strong><p style="font-size:10px;color:#8b9aa2;overflow-wrap:anywhere">${esc(event.tool_name)}</p>${event.scope.farm_ids.length>1?`<div class="source-switch">${event.scope.farm_ids.map(id=>`<button data-preview-farm="${id}" class="${id===farmId?'active':''}">${farmLabel(id)}</button>`).join('')}</div>`:''}${params([['Crop',cropName(model.farmById[farmId].crop_id)],['Object / target',args.batch_id|| (ridges.length?`Ridges ${ridges[0]}–${ridges.at(-1)}`:event.scope.actor_app)],['Duration',number((event.time_after-event.time_before)/60,1)+' min'],['Result',event.result?.status||event.status]])}<div class="mini-heading">STATE</div>${params(previewMetrics(event,farmId,ridges,snapshot))}<div class="mini-heading">TOOL INPUT</div><pre>${json(event.arguments)}</pre><details><summary>Response</summary><pre>${json(event.result)}</pre></details><button data-tool="${esc(event.tool_name)}" style="font-size:10px;color:#5d7e91;margin-top:15px">Open tool schema ↗</button><div class="empty-note">Preview shows step ${event.sequence}. ${state.pinned?'This action is selected.':'Hovering does not move world time.'}</div></div>`;
